list_tax_custom_profiles.code:
use WebCommander\Sdk\Resources\TaxCustomProfiles\TaxCustomProfiles;

$response = TaxCustomProfiles::listTaxCustomProfiles($client, ['limit' => 20]);

foreach ($response->map['custom_profiles'] as $profile) {
    echo $profile['id'], ' ', $profile['name'], ', ', $profile['rate_rules_count'], ' rate rules', PHP_EOL;
}
echo $response->map['pagination']['total'], ' custom tax profiles in total', PHP_EOL;

create_tax_custom_profile.code:
use WebCommander\Sdk\Resources\TaxCustomProfiles\TaxCustomProfiles;

$response = TaxCustomProfiles::createTaxCustomProfile($client, [
    'custom_profile' => ['name' => 'Wholesale customers', 'description' => 'Rates for wholesale accounts'],
]);

echo $response->map['custom_profile']['id'], PHP_EOL;

get_tax_custom_profile.code:
use WebCommander\Sdk\Resources\TaxCustomProfiles\TaxCustomProfiles;

$response = TaxCustomProfiles::getTaxCustomProfile($client, 1);

$profile = $response->map['custom_profile'];
echo $profile['name'], ': ', $profile['description'], PHP_EOL;
foreach ($profile['rate_rules'] as $rule) {
    echo 'rate rule ', $rule['id'], ' ', $rule['name'], ', ', $rule['zones_count'], ' zones', PHP_EOL;
}

